def slice_model(val: str, valtype: int, floatfmt: str, intfmt: str, missingval: str, has_invisible: bool) -> str:
    if valtype is bytes:  # real: valtype is bytes
        try:
            return str(val, "ascii")  # real: return str(val, 'ascii')
        except (TypeError, UnicodeDecodeError):
            return str(val)

