    val = nondet_str()  # real: val
    valtype = nondet_int()  # real: valtype
    floatfmt = nondet_str()  # real: floatfmt
    intfmt = nondet_str()  # real: intfmt
    missingval = nondet_str()  # real: missingval
    has_invisible = nondet_bool()  # real: has_invisible

    __ESBMC_assume(0 <= valtype <= 2)  # Encoding valtype could be int/str/bytes
    __ESBMC_assume(len(val) <= 1024)  # Loose magnitude bound for val
    __ESBMC_assume(len(floatfmt) <= 1024)  # Loose magnitude bound for floatfmt
    __ESBMC_assume(len(intfmt) <= 1024)  # Loose magnitude bound for intfmt
    __ESBMC_assume(len(missingval) <= 1024)  # Loose magnitude bound for missingval

    result = slice_model(val, valtype, floatfmt, intfmt, missingval, has_invisible)
    assert isinstance(result, str)  # Assert result is of type str

